import unittest
from candidate import remove_duplicates

class TestRemoveDuplicates(unittest.TestCase):
    def test_normal_case_single_occurrence(self):
        self.assertEqual(remove_duplicates([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_normal_case_multiple_duplicates(self):
        self.assertEqual(remove_duplicates([1, 2, 3, 2, 4, 3, 5]), [1, 4, 5])

    def test_empty_list(self):
        self.assertEqual(remove_duplicates([]), [])

    def test_single_element_list(self):
        self.assertEqual(remove_duplicates([7]), [7])

    def test_all_duplicates(self):
        self.assertEqual(remove_duplicates([1, 1, 1, 1]), [])

    def test_preserves_order(self):
        self.assertEqual(remove_duplicates([3, 1, 2, 1, 4, 2]), [3, 4])

    def test_negative_numbers(self):
        self.assertEqual(remove_duplicates([-1, -2, -1, 0, -2]), [-1, 0])

    def test_mixed_numbers(self):
        self.assertEqual(remove_duplicates([-3, 0, 3, 0, 2]), [-3, 2])

    def test_duplicates_at_start(self):
        self.assertEqual(remove_duplicates([1, 1, 2, 3]), [2, 3])

    def test_duplicates_at_end(self):
        self.assertEqual(remove_duplicates([1, 2, 3, 2, 2]), [1, 3])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            remove_duplicates(None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            remove_duplicates("not a list")

    def test_list_with_non_integers(self):
        with self.assertRaises(TypeError):
            remove_duplicates([1, 2, "three", 4])

    def test_duplicate_first_occurrence(self):
        self.assertEqual(remove_duplicates([1, 1, 2]), [2])

    def test_duplicate_last_occurrence(self):
        self.assertEqual(remove_duplicates([1, 2, 2]), [1])
